mapper.update:
UPDATE sub_task
SET external_fallback_count = COALESCE(external_fallback_count, 0) + 1,
    update_time = #{now}
WHERE id = #{subTaskId}
  AND deleted = 0

mapper.select:
SELECT * FROM sub_task
WHERE assigned_agent = #{agentId}
  AND status IN ('ASSIGNED', 'IN_PROGRESS', 'REWORK')
  AND deleted = 0
ORDER BY id ASC
LIMIT #{limit}
